class HookRegistry:
    def __init__(self):
        self.hooks = {}

    def on(self, hook):
        def decorator(func):
            if hook not in self.hooks:
                self.hooks[hook] = []
            self.hooks[hook].append(func)
            return func
        return decorator

    def __call__(self, hook, *args, **kwargs):
        if hook in self.hooks:
            for handler in self.hooks[hook]:
                handler(*args, **kwargs)

