        print(f"Running command: {' '.join(command_args)}")
    if cwd:
        return subprocess.run(command_args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL, env=env, check=True)
