        self.ansible_config_path = ansible_config_path

    def inject_config(self):
        if 'ANSIBLE_CONFIG' not in os.environ:
            os.environ['ANSIBLE_CONFIG'] = self.ansible_config_path

import json
from xml.etree import ElementTree as ET
from typing import Union, Any

RequestType = Union[str, bytes]

def identify_request(request: RequestType) -> bool:
    if isinstance(request, str):
        try:
            data = json.loads(request)
            return 'events' in data
        except json.JSONDecodeError:
            pass
    elif isinstance(request, bytes):
        try:
            xml_data = ET.fromstring(request.decode())
            return xml_data.tag == 'Magic_ENV_TAG'
        except ET.ParseError:
            pass
    return False

