from pytz import timezone
from datetime import datetime

def ensure_timezone(dt, tz_name):
    tz = timezone(tz_name)
    return dt.astimezone(tz)

def format_dt(dt):
    return ensure_timezone(dt, 'UTC').strftime('%Y-%m-%d %H:%M:%S')

import re

from typing import Callable, Set, Tuple


def find_tags(text: str, replacer: Callable = None) -> Tuple[Set[str], str]:

    tags = set()

    in_code_block = False

    result_text = []


    for match in re.finditer(r'(@\w+)', text):

        tag = match.group(0)

        start, end = match.span()


        if text[start - 1] == '`' and (in_code_block or not in_code_block):

            # Check if we are starting or ending a code block

            if text[start - 2] == '`' and text[end] == '`':

                in_code_block = not in_code_block


        if not in_code_block:

            tags.add(tag)

            if replacer:

                replacement = replacer(tag[1:-1])

                text = text[:start] + replacement + text[end:]


        result_text.append(text[start:end])


    return tags, ''.join(result_text)

import requests
from typing import Optional

def fetch_content_type(url: str) -> Optional[str]:
    try:
        response = requests.head(url, headers={'User-Agent': 'Mozilla/5.0'})
        return response.headers.get('Content-Type', None)
    except requests.RequestException:
        return None

def test_tag(tag: str) -> bool:
    LEEGAL_TAG_CHARS = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-")
    return all(char in LEEGAL_TAG_CHARS for char in tag)

import json

from typing import Dict


def parse_diaspora_webfinger(document: str) -> Dict:

    webfinger_data = json.loads(document)

    hcard_url = None


    for link in webfinger_data.get("links", []):

        if link.get("type") == ["text/html", "application/xhtml+xml"]:

            hcard_url = link.get("href")

            break


    return {"hcard_url": hcard_url}

import requests
from typing import Optional

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    url = f"https://webfinger.example.com/{handle}?_format=application/jrd+json"
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.text
    except requests.RequestException:
        return None

import requests


def retrieve_diaspora_host_meta(host):

    url = f"http://{host}/api/v2/host_meta.json"

    response = requests.get(url)

    if response.status_code == 200:

        return response.json()

    else:

        return None

import requests

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    session = requests.Session()
    if method.lower() == "get":
        response = session.get(url, params=data, timeout=timeout, *args, **kwargs)
    else:
        response = session.post(url, data=data, timeout=timeout, *args, **kwargs)
    return response.text
